  "plans.eyebrow": "योजनाएं एवं विशेषताएं",
  "plans.title": "StockHaven योजनाओं की तुलना करें",
  "plans.intro": "एक खाता, आप जो भी योजना चुनें — व्यवसाय अधिकतम पाँच व्यवसायों को कवर करता है। कीमतें अमेरिकी डॉलर में मासिक हैं, और पात्र नए वेबसाइट ग्राहक एसेंशियल और बिजनेस पर एक सात-दिवसीय परीक्षण प्राप्त कर सकते हैं। किसी मौजूदा एसेंशियल सब्सक्रिप्शन को बिज़नेस में अपग्रेड करने से परीक्षण पुनः आरंभ नहीं होता है या कोई अन्य निःशुल्क परीक्षण नहीं बनता है। वेबसाइट योजना की कीमतें लागू करों, यदि कोई हों, से पहले की हैं। किसी सदस्यता को अधिकृत करने से पहले आपका सटीक शुल्क दिखाया जाएगा।",
