  "upgrade.intro": "योग्य नए ग्राहक प्रति खाता एक {days}-दिन का परीक्षण प्राप्त कर सकते हैं, प्रति योजना एक परीक्षण नहीं। एसेंशियल से बिज़नेस में बदलने से कभी भी दूसरा निःशुल्क परीक्षण शुरू नहीं होता। आप वर्तमान में",
