  "billing.cancelError.subscriptionPaidThroughUnverified": "हम आपकी भुगतान तिथि की पुष्टि नहीं कर सके। कुछ भी नहीं बदला गया — कृपया पुनः प्रयास करें, या सहायता से संपर्क करें।",
