  "billing.cancelError.subscriptionEventHistoryIncomplete": "इसे रद्द करने से पहले आपके बिलिंग इतिहास की समीक्षा की आवश्यकता है। कुछ भी नहीं बदला गया — कृपया समर्थन से संपर्क करें।",
  "billing.cancelError.eventRequiresReview": "इसे रद्द करने से पहले आपके बिलिंग इतिहास की समीक्षा की आवश्यकता है। कुछ भी नहीं बदला गया — कृपया समर्थन से संपर्क करें।",
  "billing.cancelError.subscriptionCancellationUnavailable": "रद्दीकरण पूरा नहीं किया जा सका। कुछ भी नहीं बदला गया — आपकी सदस्यता और पहुँच बिल्कुल वैसी ही है जैसी वे थीं। कृपया पुनः प्रयास करें, या सहायता से संपर्क करें।",
  "billing.readiness.ariaLabel": "वास्तविक एसेंशियल चेकआउट तैयारी",
  "billing.readiness.title": "एसेंशियल चेकआउट — वास्तविक खाता सुरक्षा जाँच",
  "billing.readiness.body": "कुछ भी खरीदे बिना वास्तविक सदस्यता और परीक्षण रिकॉर्ड का निरीक्षण करें। आपका मानार्थ व्यवसाय खाता और आपका पायजामा नमूना अपरिवर्तित रहेगा। इससे Stripe चेकआउट नहीं खुलता, कार्ड चार्ज नहीं होता, या योजना नहीं बदलती।",
