  "billing.readiness.unknown": "केवल पढ़ने योग्य जाँच तत्परता ({state}) स्थापित नहीं कर सकी। कुछ भी नहीं बदला।",
  "billing.readiness.ready": "Stripe चेकआउट तैयार है — कुंजियाँ, वेबहुक सत्यापन और सत्यापन सभी की पुष्टि हो गई है।",
  "billing.readiness.complimentaryProtected": "आपका मानार्थ व्यावसायिक कार्यक्षेत्र सुरक्षित है। इसे भुगतान एसेंशियल परीक्षण खाता नहीं बनना चाहिए।",
  "billing.readiness.environmentIncomplete": "Stripe चेकआउट क्रेडेंशियल, वेबहुक सत्यापन या ऐप रिटर्न पता सभी की पुष्टि नहीं की जा सकी। कोई चेकआउट प्रारंभ नहीं हो सकता।",
  "billing.readiness.ownerHasHistory": "इस स्वामी के पास पूर्व सदस्यता या परीक्षण साक्ष्य है। दूसरा चेकआउट नहीं बनाया जाना चाहिए।",
  "billing.readiness.trialAlreadyUsed": "एक परिचयात्मक परीक्षण पहले ही उपयोग किया जा चुका है या आरक्षित किया जा चुका है। कोई पुनरावर्ती परीक्षण प्रारंभ नहीं हो सकता।",
  "billing.readiness.trialEligibilityUnverified": "इस स्वामी के लिए एकमुश्त परीक्षण पात्रता सत्यापित नहीं है। चेकआउट अवरुद्ध रहता है।",
  "billing.readiness.testModeUnverified": "खाता रिकॉर्ड पढ़ने योग्य हैं, लेकिन सुरक्षित Stripe परीक्षण-मोड रोकथाम और भुगतान-नवीकरण पूर्ति सत्यापित नहीं हैं। चेकआउट अवरुद्ध रहता है।",
  "billing.readiness.entitlementNotUnique": "मौजूदा योजना की जानकारी अनुपलब्ध या अस्पष्ट है। कोई चेकआउट प्रारंभ नहीं हो सकता।",
  "billing.readiness.accountBillingIncomplete": "खाता बिलिंग इतिहास पूरा नहीं पढ़ा जा सका। कोई चेकआउट प्रारंभ नहीं हो सकता।",
  "billing.readiness.billingHistoryIncomplete": "संपूर्ण स्वामी इतिहास सत्यापित नहीं किया जा सका। कोई चेकआउट प्रारंभ नहीं हो सकता।",
  "billing.readiness.ownershipMismatch": "किसी भी सदस्यता को शुरू करने से पहले खाता स्वामित्व या बिलिंग रिकॉर्ड की समीक्षा की आवश्यकता होती है।",
  "billing.readiness.catalogUnverified": "स्वीकृत $14.99/माह सर्वर चेकआउट परिभाषा को सत्यापन की आवश्यकता है।",
  "billing.readiness.auditUnavailable": "रीड-ओनली सर्वर जाँच अनुपलब्ध थी। कोई भुगतान या खाता परिवर्तन नहीं हुआ।",
  "billing.dryRun.ariaLabel": "परीक्षण उन्नयन सिमुलेशन",
