  "billing.dryRun.body": "इस ब्राउज़र में पूरी तरह से काल्पनिक रिकॉर्ड का उपयोग करके प्रस्तावित अपग्रेड नियमों का अभ्यास करें। यह आपके वास्तविक TEST — पायजामा पैंट नमूना, आपके वर्तमान व्यावसायिक कार्यक्षेत्र, Stripe, परीक्षण, सदस्यता या इन्वेंट्री को नहीं पढ़ता या बदलता नहीं है।",
  "billing.dryRun.runButton": "स्थानीय अपग्रेड सिमुलेशन चलाएं (कोई शुल्क नहीं)",
