  "billing.dryRun.blocked": "काल्पनिक परिदृश्य अवरुद्ध था",
  "billing.dryRun.example": "उदाहरण: आवश्यक वस्तुएं ($14.99/माह) → व्यवसाय ($29.99/माह), किसी भी लागू कर से पहले।",
  "billing.dryRun.preserved": "समान सदस्यता बरकरार रखी गई, एक मूल परीक्षण बरकरार रखा गया, और सिम्युलेटेड पायजामा इन्वेंट्री अपरिवर्तित रही। उदाहरण के लिए ग्राहक एसेंशियल पर तब तक रहता है जब तक कि वास्तविक, प्रदाता-पुष्टिकृत भुगतान नवीनीकरण बदलती पहुँच को उचित नहीं ठहराता।",
  "billing.dryRun.limitations": "एक स्थानीय सिमुलेशन Stripe सदस्यता परिवर्तन, भुगतान, वेबहुक, कर-समावेशी उद्धरण, लाइव सदस्यता या आपके वास्तविक व्यावसायिक रिकॉर्ड का परीक्षण नहीं करता है।",
