  "exports.eyebrow": "डेटा",
  "exports.title": "निर्यात और बैकअप",
  "exports.subtitleStart": "डाउनलोड हमेशा सीमित होते हैं",
  "exports.subtitleRest": ". प्रत्येक फ़ाइल पर व्यवसाय का नाम और उसके बनने की तारीख अंकित होती है।",
  "exports.createBusinessFirst": "पहले एक व्यवसाय बनाएं — निर्यात किसी व्यवसाय का होता है, ऐप का नहीं।",
  "exports.lockedTitle": "CSV और Excel निर्यात एक व्यावसायिक सुविधा है",
  "exports.lockedDesc": "आपका कार्यक्षेत्र आवश्यक योजना पर है। व्यवसाय CSV और Excel निर्यात, स्टॉक मूल्यांकन, असीमित उत्पाद और कर्मचारी, आपूर्तिकर्ता, खरीदारी और बंडल जोड़ता है।",
  "exports.seeBusiness": "देखें कि व्यवसाय में क्या शामिल है",
  "exports.whatTheseAre": "ये फ़ाइलें क्या हैं",
  "exports.about1": "प्रत्येक डेटासेट CSV या वास्तविक Excel कार्यपुस्तिका (.xlsx) के रूप में आता है — पूर्ण इन्वेंट्री कार्यपुस्तिका केवल Excel में है, प्रति डेटासेट एक शीट के साथ। CSV फ़ाइलें Excel, Numbers, Google Sheets और अधिकांश स्टॉक ऐप्स में खुलती हैं। UTF-8 टेक्स्ट, उद्धृत अल्पविराम, नोट्स में लाइन ब्रेक और कोड में अग्रणी शून्य सभी संरक्षित हैं, और सूत्र की तरह शुरू होने वाली कोशिकाएं निष्क्रिय कर दी जाती हैं इसलिए एक स्प्रेडशीट उन्हें टेक्स्ट के रूप में खोलती है।",
  "exports.about2": "Excel फ़ाइलों में, SKU, UPCs, ISBN और बारकोड टेक्स्ट सेल हैं — कभी भी वैज्ञानिक संकेतन नहीं होता है और कभी भी शून्य नहीं काटा जाता है — कॉलम की चौड़ाई, हेडर फ़िल्टर और मुद्रा या मात्रा प्रारूप लागू होते हैं। संपूर्ण इन्वेंट्री कार्यपुस्तिका उत्पादों, स्टॉक स्तर, स्थानों और गतिविधियों को अलग-अलग शीट पर रखती है।",
  "exports.about3": "बहुत बड़े निर्यात प्रति डेटासेट 20,000 पंक्तियों पर रुकते हैं — जब ऐसा होता है तो फ़ाइल नाम ऐसा कहता है (छोटा-20000), इसलिए एक आंशिक फ़ाइल कभी भी पूर्ण नहीं होती है।",
  "exports.about4": "बैकअप आपके डेटा का एक स्नैपशॉट है, एक-क्लिक पुनर्स्थापना नहीं। इसे पुनर्स्थापित करना एक मैन्युअल, समीक्षा-पहला काम है, इसलिए फ़ाइल को सुरक्षित रखें — ऐप में कुछ भी अभी तक हटाए गए व्यवसाय को फिर से नहीं बना सकता है। ऐप कोड और बेस44 प्लेटफ़ॉर्म बैकअप को इन फ़ाइलों से अलग से प्रबंधित किया जाता है।",
  "exports.about5": "फ़ोटो और अनुलग्नक को उनके संग्रहीत लिंक के रूप में सूचीबद्ध किया गया है — छवि फ़ाइलें स्वयं डाउनलोड में पैक नहीं की गई हैं।",
  "exports.backupTitle": "पूर्ण बैकअप",
  "exports.backupDesc": "इस व्यवसाय के उत्पादों, स्थानों, स्टॉक स्तर, संपूर्ण मूवमेंट लेजर, आपूर्तिकर्ताओं, खरीदारी, ऑर्डर, रिटर्न, गिनती और लिस्टिंग के साथ एक फ़ाइल — साथ ही इसकी प्रोफ़ाइल सेटिंग्स। इसे ऐसी जगह रखें जहाँ आपका नियंत्रण हो।",
  "exports.backupIncludes1": "उत्पाद, कोड, लागत और नोट्स",
  "exports.backupIncludes2": "स्थान और प्रति-स्थान मात्रा",
