  "import.eyebrow": "डेटा",
  "import.title": "आयात केंद्र",
  "import.subtitleStart": "तीन अलग-अलग स्प्रेडशीट ऑपरेशन, इसलिए मूल्य सुधार कभी भी स्टॉक रसीद के रूप में नहीं आ सकता है। सब कुछ अंदर आ जाता है",
  "import.subtitleRest": "केवल, और ड्राई रन पूरा होने तक कुछ भी नहीं लिखा जाता है।",
  "import.createBusinessFirst": "पहले एक व्यवसाय बनाएं — आयातित उत्पाद एक व्यवसाय के अंतर्गत आते हैं।",
  "import.createBusinessFirstShort": "पहले एक बिजनेस बनाएं।",
  "import.whatEachDoes": "प्रत्येक ऑपरेशन क्या करता है",
  "import.createTitle": "नए उत्पाद बनाएं",
  "import.createDesc": "उन पंक्तियों को जोड़ता है जो अभी तक कैटलॉग में नहीं हैं। पहले से उपयोग में आने वाले डुप्लिकेट SKU और बारकोड को छोड़ दिया जाता है, और शुरुआती स्टॉक रसीद के रूप में आपके द्वारा चुने गए स्थान पर आ सकता है।",
  "import.updateTitle": "मौजूदा उत्पादों को अद्यतन करें",
  "import.updateDesc": "SKU द्वारा प्रत्येक पंक्ति से मेल खाता है या ID रिकॉर्ड करता है और प्रस्तावित नए के बगल में पुराना मान दिखाता है। जब तक आप रिक्त स्थान साफ़ करने के लिए नहीं कहते, तब तक रिक्त सेल सहेजे गए मान को अकेला छोड़ देते हैं, और मात्राओं को कभी नहीं छुआ जाता है।",
  "import.receiveModeTitle": "स्टॉक प्राप्त करें",
  "import.receiveModeDesc": "आने वाली मात्राओं को एक स्थान पर जोड़ता है और प्रत्येक पंक्ति के लिए मूवमेंट लेजर में एक रसीद लिखता है। प्रत्येक बैच को चिह्नित किया गया है, इसलिए एक ही शीट दो बार प्राप्त नहीं की जा सकती।",
  "import.excelNote": "Excel कार्यपुस्तिकाएँ (.xlsx) सीधे पढ़ी जाती हैं — वर्कशीट चुनें और कॉलम आपके लिए मेल खाते हैं। कोड संपूर्ण रहते हैं: टेक्स्ट के रूप में सहेजा गया एक UPC अपने अंक और अग्रणी शून्य रखता है। जिन पंक्तियों को आयात नहीं किया जा सकता उन्हें कारण सहित सूचीबद्ध किया गया है",
