  "print.supplierBlockedDesc": "आपूर्तिकर्ता दस्तावेज़ व्यवसाय योजना के साथ चलते हैं — आपूर्तिकर्ता, क्रय और खरीद आदेश। अब आपके पास जो कुछ भी है वह काम करता रहता है।",
