  "settings.trial.cancelKeeps": "आपके परीक्षण के दौरान रद्द करने पर आपके पास पूरे 7 दिन रहते हैं — पहुँच {date} पर समाप्त होती है, और आपसे शुल्क नहीं लिया जाएगा।",
  "staff.access.noSeatBody": "आपके खाते में इस व्यवसाय के लिए कोई स्टाफ सीट नहीं है, इसलिए इसका स्टॉक बंद रहता है। मालिक से आपको स्टाफ और भूमिकाओं में जोड़ने के लिए कहें।",
  "staff.access.noSeatTitle": "यह व्यवसाय आपके लॉगिन के लिए खुला नहीं है",
  "staff.access.pendingBody": "इस व्यवसाय के पास आपके ईमेल के लिए एक निमंत्रण है जिसे सक्रिय नहीं किया गया है। मालिक से अपने स्टाफ की स्थिति को सक्रिय पर सेट करने के लिए कहें। तब तक यहाँ कुछ भी दिखाई नहीं देता।",
  "staff.access.pendingTitle": "आपका आमंत्रण अभी सक्रिय नहीं है",
  "staff.access.signOut": "साइन आउट",
  "staff.access.suspendedBody": "एक व्यवस्थापक ने सक्रिय व्यवसाय के लिए इस कर्मचारी खाते को निलंबित कर दिया है। उनसे आपको वापस सक्रिय पर सेट करने के लिए कहें, फिर दोबारा साइन इन करें।",
  "staff.access.suspendedTitle": "आपकी पहुँच रोक दी गई है",
  "staff.addFirst": "पहले स्टाफ सदस्य को जोड़ें",
  "staff.addMember": "स्टाफ सदस्य जोड़ें",
  "staff.emptyBody": "एक व्यक्ति जोड़ें, उन्हें एक भूमिका और उससे जुड़ी अनुमतियाँ दें, और उन्हें इस व्यवसाय में साइन इन करने के लिए ईमेल द्वारा आमंत्रित किया जाता है।",
  "staff.emptyTitle": "अभी तक कोई स्टाफ नहीं है",
  "staff.eyebrow": "टीम",
  "staff.how.p1": "प्रत्येक सदस्य की एक भूमिका और उनकी अपनी अनुमति सूची होती है, इसलिए आप एक भूमिका से शुरुआत कर सकते हैं और नई भूमिका बनाए बिना एक चीज़ बदल सकते हैं। किसी भूमिका को संपादित करने से उस पर पहले से मौजूद सदस्यों को फिर से नहीं लिखा जाता है — किसी सदस्य को उनकी भूमिका डिफ़ॉल्ट को फिर से लागू करने के लिए खोलें।",
  "staff.how.p2": "कस्टम भूमिकाएँ एक व्यावसायिक विशेषता हैं: एसेंशियल्स पाँच अंतर्निहित भूमिकाओं (मालिक, प्रबंधक, स्टॉक क्लर्क, बिक्री क्लर्क, दर्शक) का उपयोग करता है।",
  "staff.how.p3": "निमंत्रण ईमेल द्वारा भेजे जाते हैं। कोई सदस्य केवल एक बार स्वीकार करने के बाद ही साइन इन कर सकता है, और इस सूची से किसी को हटाने से उसका ऐप खाता नहीं हटता है।",
  "staff.how.p4": "स्टोर वह स्थान है जिसे किसी व्यक्ति को सौंपा गया है। यह उनके कार्ड पर दर्ज है; वे क्या खोल सकते हैं यह अभी भी उनकी भूमिका और अनुमतियों से तय होता है।",
  "staff.how.p5": "अनुमतियाँ तय करती हैं कि प्रत्येक व्यक्ति क्या खोल सकता है: उनकी भूमिका के बाहर मेनू आइटम छिपे हुए हैं, और एक अवरुद्ध पता पृष्ठ के बजाय \"आपकी भूमिका पर नहीं\" नोटिस दिखाता है। अगली बार जब वह व्यक्ति ऐप लोड करता है तो एक परिवर्तन लागू होता है; किसी सदस्य को निलंबित करने से वे पूरी तरह से बंद हो जाते हैं।",
  "staff.how.p6": "प्रशासक सभी डेटा को देख और बदल सकते हैं, ऐप उपयोगकर्ताओं और भूमिकाओं को प्रबंधित कर सकते हैं, और कभी भी स्टाफ की भूमिका तक सीमित नहीं होते हैं। कोई व्यक्ति जिसके पास कोई स्टाफ रिकॉर्ड नहीं है — एक नए व्यवसाय का मालिक — पूरी पहुँच रखता है।",
  "staff.howTitle": "कर्मचारी और भूमिकाएँ कैसे काम करती हैं",
