  "payroll.dd.steps.body": "1. आपको एक व्यावसायिक बैंक खाता चाहिए जो ACH भुगतान भेज सके। 2. प्रत्येक टीम सदस्य से हस्ताक्षरित प्राधिकरण फ़ॉर्म एकत्र करें - एक रद्द चेक संख्याओं को सत्यापित करने में मदद करता है। 3. वेतन दिवस से 2-3 कार्य दिवस पहले पेरोल भेजें ताकि पैसे समय पर पहुँचें। 4. अधिकांश राज्यों में टीम सदस्य की लिखित सहमति आवश्यक है। यह ऐप फ़ॉर्म एकत्र करता है और आपको चरणों से गुज़रने में मदद करता है - पैसे भेजना वास्तव में आपके अपने बैंक के माध्यम से होता है।",
