  "workforce.settings.selfClock": "कर्मचारियों को स्वयं क्लॉक इन और आउट करने दें",
  "workforce.settings.selfClockHelp": "जब यह चालू होता है, तो टीम सदस्य अपने स्वयं के साइन-इन से क्लॉक इन और आउट करते हैं।",
