  "workforce.inbox.help": "आपकी टीम के लिए क्लॉक इवेंट, छुट्टी के जवाब, कार्य, वेतन पर्चियाँ और शेड्यूल परिवर्तन, सबसे नए पहले।",
  "workforce.messages.back": "सभी वार्तालाप",
  "workforce.messages.empty": "अभी तक कोई वार्तालाप नहीं है। ऊपर दिए गए बटन से एक शुरू करें।",
  "workforce.messages.emptyThread": "अभी तक कोई संदेश नहीं है। शुरू करने के लिए नमस्ते कहें।",
  "workforce.messages.help": "आपकी टीम के साथ निजी एक-से-एक संदेश — किसी अन्य ऐप की ज़रूरत नहीं। वार्तालाप में केवल दो लोग ही इसे पढ़ सकते हैं, साथ ही व्यवसाय का मालिक, जो अपने स्टोर की देखरेख करता है।",
