  "auth.sameEmailNotice": "क्या आपके पास Google Play या App Store से हमारा ऐप पहले से है? यहाँ उसी ईमेल का उपयोग करें — वह जिससे आप ऐप में साइन इन करते हैं — ताकि आपकी दुकान और आपकी इन्वेंट्री आपके साथ आएँ। एक अलग ईमेल एक बिल्कुल नया, खाली स्टोरफ़्रंट शुरू करता है।",
