  "recovery.emailMeCode": "मेरे बैकअप ईमेल पर एक कोड ईमेल करें",
  "recovery.emailMeCodeHint": "यदि आपने एक बैकअप ईमेल सेट अप किया है, तो हम वहाँ एक 6-अंकों का कोड भेजेंगे। आपके खाते की सुरक्षा के लिए, यह पेज हमेशा उसी तरह जवाब देता है — चाहे कोड भेजा गया हो या न हो।",
  "recovery.codeSent": "यदि आपका बैकअप ईमेल फ़ाइल पर है, तो एक 6-अंकों का कोड अभी वहाँ जा रहा है। यह 10 मिनट में समाप्त होता है।",
