  "recovery.changeIntro": "आप अंदर हैं — केवल एक चरण के लिए: अपने खाते के लिए नया ईमेल चुनें। आपकी दुकान, आपकी इन्वेंट्री और आपकी टीम पहुँच सभी इसके साथ चलती हैं।",
  "recovery.doneBody": "आपका खाता ईमेल बदल गया है और यह साइन-इन अब फिर से आपका नियमित साइन-इन है। वापसी पर स्वागत है।",
  "recovery.doneButton": "मेरी दुकान पर जारी रखें",
  "settings.security.title": "सुरक्षा और अतिरिक्त कुंजियाँ",
  "settings.security.description": "अपनी अतिरिक्त कुंजियाँ ज़रूरत पड़ने से पहले सेट अप करें: यदि आप कभी अपने खाता ईमेल तक पहुँच खो देते हैं, तो वे ही हैं जिनसे आप अपनी दुकान वापस पाते हैं।",
  "settings.security.genericError": "कुछ ग़लत हो गया। कृपया फिर से प्रयास करें।",
  "settings.security.accountEmail": "खाता ईमेल",
  "settings.security.backupCodesTitle": "बैकअप कोड",
