  "settings.security.codesOnceWarning": "ये कोड केवल एक बार दिखाए जाते हैं — हम केवल एक उलझी हुई प्रतिलिपि रखते हैं, इसलिए हम भी इन्हें फिर से नहीं दिखा सकते। एक नया सेट बनाने से हर पुराना कोड रद्द हो जाता है।",
  "settings.security.printCodes": "ये कोड प्रिंट करें",
  "settings.security.backupEmailTitle": "बैकअप ईमेल",
  "settings.security.backupEmailDesc": "एक दूसरा ईमेल पता जिसे आप नियंत्रित करते हैं। यदि आपका मुख्य ईमेल कभी पहुँच से बाहर हो, तो इसके बजाय यहाँ एक पुनर्प्राप्ति कोड भेजा जा सकता है।",
