  "pos.events.heldPlanNote": "नीचे कुछ बिक्री तब आईं जब यह स्टोर Business योजना पर नहीं था। उन्हें सुरक्षित रखा गया और कुछ नहीं गिना गया। अब जब स्टोर Business पर है, तो आप इन्हें गिन सकते हैं।",
